-- Generated by `pnpm db:supabase-sync` — DO NOT EDIT. Idempotent; re-emitted after schema changes.
-- = `pnpm --filter @restomatch/db provision-rls` (PROVISION_STORAGE_RLS=1) as a migration.

-- 1. The non-owner tenant role. NOLOGIN and NO password in git: after the first
--    deploy the owner runs  ALTER ROLE restomatch_app WITH LOGIN PASSWORD '…';
--    (docs/SUPABASE-GITHUB-DEPLOY.md), or provision-rls with APP_ROLE_PASSWORD.
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'restomatch_app') then
    create role restomatch_app nologin;
  end if;
end $$;

-- 2. Core tenant RLS (packages/db/drizzle/rls/0002_core_tenant_rls.sql)
-- ───────────────────────────────────────────────────────────────────────────
-- Per-restaurant Row-Level Security for RestoMatch core tables.
-- Apply during Phase-3 Supabase consolidation (NOT via pnpm db:migrate).
-- Also applied to the local test DB by the RLS attack suite
-- (packages/api/src/__tests__/rls.attack.test.ts) via applyCoreTenantRls().
--
-- Tenancy key: every protected row carries restaurant_id. The app sets the
-- active restaurant per transaction:  SET LOCAL app.current_restaurant_id = '<uuid>';
-- (wired in packages/api/src/trpc.ts memberProcedure via withRestaurant()).
-- Apply on a role that is NOT the table owner / NOT service_role (both bypass RLS).
--
-- The worker connects with a service (RLS-bypassing) role BY DESIGN: cron jobs
-- (baselines, daily expectations, outbox) are inherently cross-tenant. Worker
-- tenant safety relies on the explicit payload-ownership guards in its jobs.
-- ───────────────────────────────────────────────────────────────────────────

create schema if not exists app;

-- Reads the active restaurant from the per-transaction GUC (NULL if unset).
create or replace function app.current_restaurant_id() returns uuid
  language sql stable
  as $$ select nullif(current_setting('app.current_restaurant_id', true), '')::uuid $$;

-- Reads the acting user from the per-transaction GUC (NULL if unset).
create or replace function app.current_user_id() returns uuid
  language sql stable
  as $$ select nullif(current_setting('app.current_user_id', true), '')::uuid $$;

-- The root tenant table keys on `id` rather than `restaurant_id`.
alter table restaurants enable row level security;
drop policy if exists restaurants_tenant on restaurants;
create policy restaurants_tenant on restaurants
  using (id = app.current_restaurant_id());

-- Tenant creation (onboarding.createRestaurant) generates the restaurant uuid
-- in code and sets the GUC to it BEFORE inserting, so the new row satisfies
-- restaurants_tenant (and INSERT..RETURNING can see it). No GUC ⇒ no inserts,
-- anywhere. (Drop the bootstrap policies earlier revisions created.)
drop policy if exists restaurants_create on restaurants;

-- Every table that carries restaurant_id gets the same per-restaurant policy.
-- Idempotent and column-aware: tables without restaurant_id are skipped
-- (children like po_lines/gr_lines/invoice_lines/product_aliases get explicit
-- join-based policies below — keep that list in sync with the schema).
do $$
declare t text;
begin
  foreach t in array array[
    'memberships','invitations','suppliers','products',
    'supplier_catalog_items','catalog_imports',
    'purchase_orders','goods_receipts','invoices','invoice_scans',
    'storage_namespaces',
    'match_runs','discrepancies','activity_events','price_history',
    'price_baselines','approval_rules','audit_log','procurement_connections',
    'email_inboxes','supplier_integrations','notifications_outbox',
    -- S13 ingest (migration 0050)
    'ingest_channels','ingest_senders','ingest_messages','ingest_documents'
  ] loop
    if exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = t and column_name = 'restaurant_id'
    ) then
      execute format('alter table %I enable row level security;', t);
      execute format('drop policy if exists %I on %I;', t || '_tenant', t);
      execute format(
        'create policy %I on %I using (restaurant_id = app.current_restaurant_id());',
        t || '_tenant', t
      );
    else
      raise exception 'RLS: table % is listed but has no restaurant_id column', t;
    end if;
  end loop;
end $$;

drop policy if exists memberships_bootstrap on memberships;

-- A user may always list their own memberships. onboarding procedures run as
-- userScopedProcedure (packages/api/src/trpc.ts), which sets only the user GUC.
drop policy if exists memberships_self on memberships;
create policy memberships_self on memberships
  for select using (user_id = app.current_user_id());

-- A user may see the restaurants they belong to (myMemberships joins
-- restaurants for the name before any restaurant GUC exists). The memberships
-- subquery is itself RLS-filtered to the caller's own rows via memberships_self.
drop policy if exists restaurants_member_select on restaurants;
create policy restaurants_member_select on restaurants
  for select using (
    exists (
      select 1 from memberships m
      where m.restaurant_id = restaurants.id
        and m.user_id = app.current_user_id()
    )
  );

-- users is a PII directory, not just credentials: scope reads to the caller's
-- own row. Auth.js manages users/accounts/sessions on the auth (owner/service)
-- connection, which bypasses RLS; the tenant app role gets no other access
-- (see ensureRlsAppRole revokes).
alter table users enable row level security;
drop policy if exists users_self on users;
create policy users_self on users
  for select using (id = app.current_user_id());

-- ── Child tables without their own restaurant_id: join through the parent ──

alter table invoice_lines enable row level security;
drop policy if exists invoice_lines_tenant on invoice_lines;
create policy invoice_lines_tenant on invoice_lines
  using (
    exists (
      select 1 from invoices i
      where i.id = invoice_lines.invoice_id
        and i.restaurant_id = app.current_restaurant_id()
    )
  );

alter table po_lines enable row level security;
drop policy if exists po_lines_tenant on po_lines;
create policy po_lines_tenant on po_lines
  using (
    exists (
      select 1 from purchase_orders po
      where po.id = po_lines.po_id
        and po.restaurant_id = app.current_restaurant_id()
    )
  );

alter table gr_lines enable row level security;
drop policy if exists gr_lines_tenant on gr_lines;
create policy gr_lines_tenant on gr_lines
  using (
    exists (
      select 1 from goods_receipts gr
      where gr.id = gr_lines.gr_id
        and gr.restaurant_id = app.current_restaurant_id()
    )
  );

alter table product_aliases enable row level security;
drop policy if exists product_aliases_tenant on product_aliases;
create policy product_aliases_tenant on product_aliases
  using (
    exists (
      select 1 from products p
      where p.id = product_aliases.product_id
        and p.restaurant_id = app.current_restaurant_id()
    )
  );

-- ── Billing & entitlements: scoped through the restaurant→billing_account link ─
-- billing_accounts / subscriptions / usage_counters have no restaurant_id (a
-- chain shares one account); a member sees them iff the CURRENT restaurant
-- links to that account. The restaurants subquery is itself RLS-filtered to the
-- current restaurant, so this resolves to "the current restaurant's account".
-- Writes happen on the owner/service connection (worker metering, admin, webhooks).

alter table billing_accounts enable row level security;
drop policy if exists billing_accounts_tenant on billing_accounts;
create policy billing_accounts_tenant on billing_accounts
  for select using (
    exists (
      select 1 from restaurants r
      where r.billing_account_id = billing_accounts.id
        and r.id = app.current_restaurant_id()
    )
  );

alter table subscriptions enable row level security;
drop policy if exists subscriptions_tenant on subscriptions;
create policy subscriptions_tenant on subscriptions
  for select using (
    exists (
      select 1 from restaurants r
      where r.billing_account_id = subscriptions.billing_account_id
        and r.id = app.current_restaurant_id()
    )
  );

alter table usage_counters enable row level security;
drop policy if exists usage_counters_tenant on usage_counters;
create policy usage_counters_tenant on usage_counters
  for select using (
    exists (
      select 1 from restaurants r
      where r.billing_account_id = usage_counters.billing_account_id
        and r.id = app.current_restaurant_id()
    )
  );

-- billing_events: webhook log. No member access at all (admin/service only).
alter table billing_events enable row level security;

-- leads: anyone may submit (public landing form), nobody on the tenant role may
-- read (admin reads via the owner connection). RLS-enabled with only an INSERT
-- policy ⇒ SELECT returns zero rows for the app role.
alter table leads enable row level security;
drop policy if exists leads_insert on leads;
create policy leads_insert on leads for insert with check (true);

-- plans is public pricing reference data — intentionally left without RLS so
-- the catalog is readable everywhere.

-- ── Completeness invariant: has restaurant_id ⇒ RLS enabled ────────────────
-- The allowlist above is hand-maintained while the app role's grants include
-- all future tables; this guard turns a forgotten table from a silent
-- cross-tenant exposure into a loud failure at apply time.
do $$
declare missing text;
begin
  select string_agg(c.table_name, ', ') into missing
  from information_schema.columns c
  join pg_class pc on pc.relname = c.table_name
  join pg_namespace pn on pn.oid = pc.relnamespace and pn.nspname = 'public'
  where c.table_schema = 'public'
    and c.column_name = 'restaurant_id'
    and not pc.relrowsecurity;
  if missing is not null then
    raise exception 'RLS: tables with restaurant_id but row security disabled: %', missing;
  end if;
end $$;

-- ── Credential-auth identity tables (Epic B/C): deny the tenant app role ─────
-- user_credentials / password_reset_tokens / user_recovery_codes are managed
-- ONLY on the owner auth connection (server actions / route handlers). The
-- tenant role must never read password hashes / TOTP secrets, replay reset
-- tokens or recovery codes, or forge a tokenVersion bump. This mirrors the
-- REVOKE in packages/db/src/rls.ts (ensureRlsAppRole) for the production
-- cutover. Gated on role + table existence so it is a safe no-op pre-0019 or on
-- a DB where the app role has not been provisioned yet.
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'restomatch_app') then
    if to_regclass('public.user_credentials') is not null then
      execute 'revoke all on user_credentials from restomatch_app';
    end if;
    if to_regclass('public.password_reset_tokens') is not null then
      execute 'revoke all on password_reset_tokens from restomatch_app';
    end if;
    if to_regclass('public.user_recovery_codes') is not null then
      execute 'revoke all on user_recovery_codes from restomatch_app';
    end if;
  end if;
end $$;

-- 3. Append-only audit log (packages/db/drizzle/rls/0003_audit_immutable.sql)
-- ───────────────────────────────────────────────────────────────────────────
-- audit_log → append-only (immutable, tamper-evident).  Apply AFTER 0002.
--
-- Threat (R-27): the blanket app-role grant + the 0002 ALL policy let the
-- tenant role UPDATE/DELETE its OWN audit rows. A compromised tenant code path
-- could therefore erase/forge its audit trail — failing the integrity duty of
-- Privacy-Law Amendment 13 / Level-3.
--
-- Three layers, defence-in-depth:
--   1. Split the 0002 `audit_log_tenant` ALL policy into SELECT + INSERT only
--      (no UPDATE/DELETE policy ⇒ RLS admits no such rows for the app role).
--   2. REVOKE update,delete on audit_log from restomatch_app (ensureRlsAppRole)
--      ⇒ permission-denied at the privilege layer (the primary gate).
--   3. A BEFORE UPDATE/DELETE trigger that raises for any NON-owner / NON-bypass
--      role ⇒ even if a future grant drifts and re-grants the privilege, the row
--      mutation still fails. RLS-bypassing maintenance roles (the owner used by
--      migrations/retention/DR and the worker service_role, plus ON DELETE
--      CASCADE from restaurants) remain able to purge — that is the trusted
--      maintenance plane, not the tenant plane.
-- ───────────────────────────────────────────────────────────────────────────

create schema if not exists app;

-- 1) Replace the 0002 ALL policy with append-only SELECT + INSERT policies.
alter table audit_log enable row level security;
drop policy if exists audit_log_tenant on audit_log;

drop policy if exists audit_log_select on audit_log;
create policy audit_log_select on audit_log
  for select using (restaurant_id = app.current_restaurant_id());

drop policy if exists audit_log_insert on audit_log;
create policy audit_log_insert on audit_log
  for insert with check (restaurant_id = app.current_restaurant_id());

-- 3) Immutability trigger. Allows mutation only for trusted maintenance roles:
--    superusers, roles flagged BYPASSRLS (service_role / worker), and the table
--    owner (migrations, retention purge, cascade deletes). Everyone else — most
--    importantly the non-owner restomatch_app tenant role — is rejected.
create or replace function app.audit_log_is_maintenance_role() returns boolean
  language sql stable as $$
  select exists (
      select 1 from pg_roles r
      where r.rolname = current_user and (r.rolsuper or r.rolbypassrls)
    )
    or current_user = (
      select pg_catalog.pg_get_userbyid(relowner)
      from pg_class where oid = 'public.audit_log'::regclass
    )
$$;

create or replace function app.audit_log_immutable() returns trigger
  language plpgsql as $$
begin
  if app.audit_log_is_maintenance_role() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  raise exception 'audit_log is append-only: % is not permitted (role %)', tg_op, current_user
    using errcode = 'check_violation';
end;
$$;

drop trigger if exists audit_log_no_update_delete on audit_log;
create trigger audit_log_no_update_delete
  before update or delete on audit_log
  for each row execute function app.audit_log_immutable();

-- 4. Grants / revokes (packages/db/src/rls.ts → rlsAppRoleGrantsSql, same as ensureRlsAppRole)
grant usage on schema public to restomatch_app;
      grant usage on schema app to restomatch_app;
      grant select, insert, update, delete on all tables in schema public to restomatch_app;
      alter default privileges in schema public
        grant select, insert, update, delete on tables to restomatch_app;
      grant execute on all functions in schema app to restomatch_app;

      -- Identity tables are a separate trust zone: Auth.js manages them on the
      -- auth (owner/service) connection. The tenant app role keeps only
      -- RLS-scoped SELECT on users (users_self policy) and nothing else —
      -- otherwise a compromised tenant path could read magic-link tokens and
      -- the full user directory.
      revoke all on accounts, sessions, verification_tokens, authenticators
        from restomatch_app;
      revoke insert, update, delete on users from restomatch_app;

      -- Billing/catalog tables are written only by the worker, admin, and
      -- webhooks on the owner/service connection. The tenant app role gets
      -- read-only access (plans is public reference data; billing_accounts/
      -- subscriptions/usage_counters are RLS-scoped SELECT). Crucially, plans
      -- has NO RLS, so without this revoke the blanket grant would let a tenant
      -- rewrite plan pricing/limits and self-escalate every tenant on the plan.
      revoke insert, update, delete on
        plans, billing_accounts, subscriptions, usage_counters, billing_events
        from restomatch_app;
      -- leads: public submit (INSERT policy) only; no edits/reads of others.
      revoke update, delete on leads from restomatch_app;

      -- audit_log is APPEND-ONLY (0003): the tenant role may INSERT + SELECT its
      -- own rows but never mutate/erase them. Without this revoke a compromised
      -- tenant path could rewrite or delete its own audit trail (R-27). The
      -- BEFORE UPDATE/DELETE trigger in 0003 is the defence-in-depth backstop.
      revoke update, delete on audit_log from restomatch_app;

      -- Credential auth (Epic B/C) is a separate identity trust zone managed
      -- ONLY on the owner auth connection via server actions / route handlers.
      -- The tenant app role gets NOTHING: a compromised tenant path must not be
      -- able to read password hashes / TOTP secrets, replay reset tokens or
      -- recovery codes, or forge a tokenVersion bump (session-revocation
      -- bypass). REVOKE ALL is gated on table existence so this stays a no-op on
      -- a DB that has not yet applied 0023_user_credentials.
      do $$ begin
        if to_regclass('public.user_credentials') is not null then
          execute 'revoke all on user_credentials from restomatch_app';
        end if;
        if to_regclass('public.password_reset_tokens') is not null then
          execute 'revoke all on password_reset_tokens from restomatch_app';
        end if;
        if to_regclass('public.user_recovery_codes') is not null then
          execute 'revoke all on user_recovery_codes from restomatch_app';
        end if;
      end $$;

-- 5. Storage (Supabase): the private invoice-scans bucket the app uploads to,
--    then the per-restaurant storage.objects policies (rls/0001). storage.objects
--    belongs to supabase_storage_admin; if the migration role may not alter it or
--    create policies on it, this logs a WARNING instead of failing the deploy —
--    apply rls/0001 from the SQL editor then (the doctor / verify-cutover report it).
do $$ begin
  if to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public)
    values ('invoice-scans', 'invoice-scans', false)
    on conflict (id) do update set public = false;
  end if;
end $$;

do $restomatch_storage$ begin
  if to_regclass('storage.objects') is null then
    raise notice 'restomatch: no storage schema — skipping storage policies';
    return;
  end if;
  begin
    alter table storage.objects enable row level security;
  exception when insufficient_privilege then
    raise notice 'restomatch: storage.objects RLS not altered (%), Supabase enables it by default', sqlerrm;
  end;
  begin
    execute $policies$
-- ───────────────────────────────────────────────────────────────────────────
-- STORAGE isolation for invoice scans (Supabase Storage layer).
--
-- Apply on Supabase via the OWNER / direct connection (DATABASE_URL_DIRECT) —
-- storage.buckets / storage.objects are owned by supabase_storage_admin and the
-- `postgres` role can alter them; service_role and table owners BYPASS RLS by
-- design. See docs/PR1-storage-isolation-APPLY.md for the production runbook.
--
-- The per-restaurant invoice_scans TABLE policy lives in 0002_core_tenant_rls.sql
-- (`invoice_scans` is in its tenant-table loop). This file is ONLY the storage
-- layer: bucket privacy + storage.objects per-restaurant path-prefix isolation.
--
-- Tenancy key at the storage layer: the FIRST folder segment of the object name
-- is the owning restaurant id, e.g. '<restaurant_id>/<scan-id>.pdf'. The
-- anonymous showcase keeps a single shared 'walk-ins/' prefix (demo data, no
-- tenant). app.current_restaurant_id() is set per-transaction by the app
-- (packages/api/src/trpc.ts memberProcedure → withRestaurant); it is NULL for
-- connections that never set it, so those see nothing tenant-scoped.
--
-- The policies are intentionally role-agnostic (no `to authenticated`): they are
-- gated on the GUC, so a connection only ever sees its own prefix, while
-- service_role (the app's real production storage path: server-side signed reads
-- + server-side uploads) bypasses RLS entirely. This is defense-in-depth — if a
-- non-service connection ever reaches storage.objects, the prefix gate still
-- isolates it. It also lets the CI attack-suite exercise the exact policy logic
-- against a vanilla-Postgres storage shim (see storage.attack.test.ts).
-- ───────────────────────────────────────────────────────────────────────────

-- 1) Make the bucket private. After this the app MUST serve signed URLs
--    (createSignedUrl) instead of getPublicUrl(); /object/public/... 400s.
update storage.buckets set public = false where id = 'invoice-scans';

-- 2) storage.objects per-restaurant isolation by path prefix.
-- (RLS on storage.objects is enabled separately above)

-- ── Per-tenant: first path segment must equal the active restaurant id ──
drop policy if exists invoice_scans_tenant_select on storage.objects;
create policy invoice_scans_tenant_select on storage.objects
  for select
  using (
    bucket_id = 'invoice-scans'
    and (storage.foldername(name))[1] = app.current_restaurant_id()::text
  );

drop policy if exists invoice_scans_tenant_insert on storage.objects;
create policy invoice_scans_tenant_insert on storage.objects
  for insert
  with check (
    bucket_id = 'invoice-scans'
    and (storage.foldername(name))[1] = app.current_restaurant_id()::text
  );

drop policy if exists invoice_scans_tenant_update on storage.objects;
create policy invoice_scans_tenant_update on storage.objects
  for update
  using (
    bucket_id = 'invoice-scans'
    and (storage.foldername(name))[1] = app.current_restaurant_id()::text
  )
  with check (
    bucket_id = 'invoice-scans'
    and (storage.foldername(name))[1] = app.current_restaurant_id()::text
  );

drop policy if exists invoice_scans_tenant_delete on storage.objects;
create policy invoice_scans_tenant_delete on storage.objects
  for delete
  using (
    bucket_id = 'invoice-scans'
    and (storage.foldername(name))[1] = app.current_restaurant_id()::text
  );

-- ── Anonymous showcase: a single shared 'walk-ins/' prefix (demo data only) ──
-- Narrow by prefix (never a tenant prefix), so the public landing-page receiver
-- can upload/read its own demo scans with the publishable (anon) key. It can
-- NEVER touch a '<restaurant_id>/' object because that requires the GUC above.
drop policy if exists invoice_scans_walkins_select on storage.objects;
create policy invoice_scans_walkins_select on storage.objects
  for select
  using (bucket_id = 'invoice-scans' and (storage.foldername(name))[1] = 'walk-ins');

drop policy if exists invoice_scans_walkins_insert on storage.objects;
create policy invoice_scans_walkins_insert on storage.objects
  for insert
  with check (bucket_id = 'invoice-scans' and (storage.foldername(name))[1] = 'walk-ins');
    $policies$;
  exception when insufficient_privilege then
    raise warning 'restomatch: storage.objects policies NOT applied as % (%) — run packages/db/drizzle/rls/0001_invoice_scans_rls.sql in the SQL editor', current_user, sqlerrm;
  end;
end $restomatch_storage$;

-- 6. Lock the Supabase Data API out of the schema. Supabase grants ALL on new
--    public tables/sequences to anon + authenticated by default privileges, and
--    those roles are reachable with the PUBLIC publishable key through PostgREST.
--    RestoMatch never reads tables through the Data API (supabase-js is used for
--    Storage only; all data goes through Drizzle), so they get nothing — otherwise
--    every table without RLS (plans, dsr_requests, the Auth.js identity tables)
--    would be readable/writable by anyone holding the publishable key.
do $$
declare r text;
begin
  foreach r in array array['anon', 'authenticated'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke all on all tables in schema public from %I', r);
      execute format('revoke all on all sequences in schema public from %I', r);
      execute format('alter default privileges in schema public revoke all on tables from %I', r);
      execute format('alter default privileges in schema public revoke all on sequences from %I', r);
    end if;
  end loop;
end $$;
